/* Supply-chain prototype: durable business records, local assets, scheduled obligations. */
let supplyMonth='2026-09',supplyView='all',supplyStatus='all',supplyProductSearch='',potentialSearch='',potentialFilter='all';
const supplyURLs=new Map();
const potentialDimensions=['搜索量或曝光量','类目销量','竞争机会','毛利空间','主观感受'];
const isSupply=i=>['producttrial','gallerycycle','clearance','potential','potentialcycle','develop'].includes(i.type);
const supplyToday=()=>state.supply?.today||'2026-09-25';
const supplyManager=()=>role===2&&level==='负责人';
const supplyOwner=()=>level==='员工'?employeeId:'manager-2';
function supplyVisible(i){if(isLifeTask(i))return lifeTaskVisible(i);if(i.type==='develop')return developmentVisible(i);return role===0||role===2&&(level==='负责人'||i.assigneeId===employeeId||i.creatorId===employeeId||i.reviewerId===employeeId)||i.type==='clearance'&&role===1&&level==='负责人'&&shops.includes(i.shop)&&i.stage>0;}
function supplyCanAct(i){if(isLifeTask(i))return lifeTaskCanAct(i);if(i.type==='develop')return developmentCanAct(i);if(i.type==='potentialcycle')return supplyVisible(i)&&role===2&&(i.stage===0&&(supplyManager()||employeeId===i.assigneeId)||i.stage===1&&supplyManager());if(!supplyVisible(i)||role===0)return false;if(i.type==='clearance')return i.stage===0?supplyManager():i.stage===1?role===1&&level==='负责人':i.stage===2?role===2&&(i.reviewerId==='manager-2'?supplyManager():level==='员工'&&i.reviewerId===employeeId):false;if(i.type==='gallerycycle')return i.stage===0?role===2&&(supplyManager()||employeeId===i.assigneeId):i.stage===1&&supplyManager();return i.stage===0?role===2&&(supplyManager()||i.creatorId===supplyOwner()):i.stage===1&&supplyManager();}
function supplyActor(i){if(isLifeTask(i))return i.stage===3?-1:i.stage===2?2:1;if(i.stage===stages[i.type].length-1)return -1;return i.type==='clearance'&&i.stage===1?1:2;}
function supplyHandler(i){if(isLifeTask(i))return lifeTaskHandler(i);if(i.type==='develop')return developmentHandler(i);if(i.type==='potentialcycle')return i.stage===2?'已完成':i.stage===1?'供应链负责人':developmentPerson(i.assigneeId);if(ceoIsDone(i))return '已完成';if(i.type==='clearance')return i.stage===1?'林悦 · '+i.shop:i.stage===2&&i.reviewerId!=='manager-2'?taskEmployees(2).find(x=>x.id===i.reviewerId)?.name||'指定评审人':'供应链负责人';if(i.type==='gallerycycle'&&i.stage===0)return taskEmployees(2).find(x=>x.id===i.assigneeId)?.name||'供应链负责人';if(i.type==='potential'&&i.stage===0)return i.owner;return '供应链负责人';}
function supplyAudit(d,i,note){i.history.push(`${supplyToday()} · ${role===1?'事业主理人':role===0?'系统':level==='员工'?taskEmployees(role).find(e=>e.id===employeeId)?.name:'供应链负责人'}：${note}`);i.progress=Math.round(i.stage/(stages[i.type].length-1)*100);if(ceoIsDone(i))i.completedAt??=supplyToday();d.log.push({id:i.id,at:new Date().toISOString(),by:centers[role],text:note});let doc=d.docs.find(x=>x.supplyId===i.id);if(!doc){doc={id:'SUPPLY-'+i.id,supplyId:i.id,title:i.title,center:2,scope:i.shop,category:'流程记录',source:i.id,version:0};d.docs.push(doc);}doc.body=i.history.join('\n');doc.version++;if(ceoIsDone(i))doc.category='交付成果';}
function supplyCommit(id,fn,message='已保存',reopen=true){if(storageBlocked){toast('本地存储不可用，未保存');return false;}try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&(raw.revision||0)!==(state.revision||0))throw Error('其他页面已更新，请刷新后重试');const draft=structuredClone(state);fn(draft.items.find(x=>x.id===id),draft);syncPotentialCycles(draft);draft.revision=(state.revision||0)+1;localStorage.setItem(key,JSON.stringify(draft));state=draft;render();if(id&&reopen)supplyDetail(id);else $('#overlay').innerHTML='';toast(message);return true;}catch(e){toast(e.message);return false;}}
function supplyDateAdd(date,days){const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
function supplyGenerate(d,to){const s=d.supply;const starts=[s.generatedThrough?supplyDateAdd(s.generatedThrough,1):to.slice(0,7)+'-01',s.potentialGeneratedThrough?supplyDateAdd(s.potentialGeneratedThrough,1):to.slice(0,7)+'-01'];const start=starts.sort()[0];if(start>to)return;for(let day=start;day<=to;day=supplyDateAdd(day,1)){const dow=new Date(day+'T00:00:00Z').getUTCDay(),dom=Number(day.slice(-2));for(const type of ['gallerycycle','clearance','potentialcycle']){if(day<=(type==='potentialcycle'?s.potentialGeneratedThrough||'':s.generatedThrough||''))continue;if(type==='gallerycycle'?dow!==s.rules.weekday:!(type==='clearance'?s.rules.clearanceDays:s.rules.potentialDays).includes(dom))continue;if(type!=='gallerycycle'&&d.items.filter(i=>i.type===type&&i.source==='system'&&i.cycleDate?.startsWith(day.slice(0,7))).length>=2)continue;const cycleKey=type+':'+day;if(d.items.some(i=>i.cycleKey===cycleKey))continue;const i={id:'CJ-'+d.seq++,type,cycleKey,cycleDate:day,title:day+({'gallerycycle':' · 每周供应商新品整理','clearance':' · 定期清仓计划','potentialcycle':' · 本期潜力品发现任务'}[type]),center:2,shop:'公司',owner:'供应链负责人',assigneeId:type==='potentialcycle'?s.rules.potentialAssignee:s.rules.galleryAssignee,reviewerId:'manager-2',stage:0,progress:0,light:'green',due:supplyDateAdd(day,({'gallerycycle':s.rules.galleryDays,'clearance':s.rules.clearanceDuration,'potentialcycle':s.rules.potentialDuration}[type])-1),description:({'gallerycycle':'整理所有供应商本周新品，分类、补齐资料并发布给运营选品。','clearance':'确定清仓商品、优惠及销售目标，分配项目执行并完成复盘评分。','potentialcycle':'记录本期潜力商品，补齐五维评分和证据，提交供应链负责人评审；本期关联商品全部通过才完成。'}[type]),products:[],salesRecords:[],history:['系统按周期自动生成：'+day],source:'system',createdAt:day};d.items.push(i);}}s.generatedThrough=to;s.potentialGeneratedThrough=to;}
function migrateSupply(){if(storageBlocked)return;try{const d=structuredClone(state);if(!d.supply){localStorage.setItem(key+'-before-supply-v1',JSON.stringify(state));d.supply={version:1,today:'2026-09-25',products:[],rules:{weekday:1,galleryDays:5,clearanceDays:[1,16],clearanceDuration:14,galleryAssignee:'emp-2-2'}};}d.supply.rules={potentialDays:[1,16],potentialDuration:14,potentialAssignee:'emp-2-2',...d.supply.rules};const before=d.items.length;supplyGenerate(d,d.supply.today);if(!state.supply||before!==d.items.length||JSON.stringify(d.supply)!==JSON.stringify(state.supply)){d.revision=(state.revision||0)+1;localStorage.setItem(key,JSON.stringify(d));state=d;}}catch{storageBlocked=true;}}
function supplyMonthRecords(type){return state.items.filter(i=>i.type===type&&supplyVisible(i));}
function supplyMetrics(){const month=supplyMonth;const products=state.supply.products.filter(p=>p.publishedAt?.startsWith(month));const clearances=supplyMonthRecords('clearance').map(i=>({i,r:(i.salesRecords||[]).filter(r=>r.at.startsWith(month)).at(-1)})).filter(x=>x.r);const develop=state.items.filter(i=>i.type==='develop'&&i.stage===stages.develop.length-1&&i.completedAt?.startsWith(month));const potential=supplyMonthRecords('potential').filter(i=>i.stage===2&&i.approvedAt?.startsWith(month));return {products,clearances,develop,potential};}
function supplyOverview(){const m=supplyMetrics();const all=items().filter(i=>i.center===2||actor(i)===2||i.assigned===2).filter(i=>i.due?.startsWith(supplyMonth)||!ceoIsDone(i)&&i.due<supplyMonth+'-01');const groups={goal:all.filter(i=>i.type==='goal'),sent:all.filter(i=>i.type==='task'),received:all.filter(i=>!['goal','task'].includes(i.type))};const shown=all.filter(i=>supplyView==='all'||groups[supplyView]?.includes(i)).filter(i=>supplyStatus==='all'||supplyStatus==='mine'&&canAct(i)||supplyStatus==='risk'&&(ceoIssues(i).length||i.blocked)||supplyStatus==='done'&&ceoIsDone(i));return heading('概览','先看本月业务成果，再跟进公司目标、接收的工作和下发的任务。',`<label class="field">统计月份<input type="month" id="supply-month" value="${supplyMonth}"></label>${supplyManager()?'<button id="supply-schedule">周期任务规则</button><button class="primary" data-new="task">＋ 下发任务</button>':''}`)+`<div class="supply-kpis">${[['pictures','本月新增图片数',m.products.length,'按已同步运营的新增商品主图统计'],['clearance','本月预估清仓金额','¥'+m.clearances.reduce((n,x)=>n+x.r.forecastAmount,0).toLocaleString(),'取运营本月填写的最新预估金额'],['develop','本月产品开发数量',m.develop.length,'仅统计本月流程完结的开发单'],['potential','发现潜力品数量',m.potential.length,'仅统计本月主管评审通过的商品']].map(([k,t,v,n])=>`<button class="metric" data-supply-metric="${k}"><span class="metric-title">${t}</span><strong>${v}</strong><span class="sub">${n} ↗</span></button>`).join('')}</div><div class="ceo-section-title"><div><span class="eyebrow">GOALS & EXECUTION</span><h2>管理视角 <small>向上承接、接收工作、向下派单</small></h2></div><span class="sub">演示业务日期 ${supplyToday()}</span></div><div class="principal-summary">${[['goal','公司目标','向上承接'],['received','接收的工作','系统周期任务与跨中心协作'],['sent','下发的任务','员工执行与负责人验收']].map(([k,t,n])=>`<button class="panel principal-summary-card ${supplyView===k?'selected':''}" data-supply-view="${k}"><span class="eyebrow">${n}</span><h3>${t}</h3><strong>${groups[k].filter(ceoIsDone).length} / ${groups[k].length}</strong><p class="sub">已完成 · 待处理 ${groups[k].filter(canAct).length}</p><div class="progress"><span style="width:${groups[k].length?groups[k].filter(ceoIsDone).length/groups[k].length*100:0}%"></span></div></button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>周期工作与业务入口</h2></div><div class="supply-shortcuts">${[['gallery','每周供应商新品整理','文件夹导入 → 信息整理 → 发布运营'],['clearance','每月两次组织清仓','选品定价 → 项目销售 → 复盘评分'],['potential','发现潜力品','每月两次 → 五维证据 → 主管评审']].map(([p,t,n])=>`<button data-page="${p}"><b>${t}</b><p class="sub">${n}</p></button>`).join('')}</div></section><div class="tabs">${[['all','全部事项'],['goal','公司目标'],['received','接收工作'],['sent','下发任务']].map(([v,n])=>`<button data-supply-view="${v}" class="${supplyView===v?'active':''}">${n}</button>`).join('')}</div><div class="tabs">${[['all','全部状态'],['mine','待我处理'],['risk','延期与卡点'],['done','已完成']].map(([v,n])=>`<button data-supply-status="${v}" class="${supplyStatus===v?'active':''}">${n}</button>`).join('')}</div>${supplyWorkTable(shown)}${m.potential.length?'<h2>本月评审通过的潜力品</h2>'+potentialCards(m.potential):''}`;}
function supplyWorkTable(arr){return `<section class="panel"><div class="table-wrap"><table><thead><tr><th>事项 / 来源</th><th>当前处理人</th><th>进度 / 截止日期</th><th>状态与卡点</th><th></th></tr></thead><tbody>${arr.map(i=>`<tr data-supply-row="${i.id}"><td><b>${esc(i.title)}</b> ${taskPriorityBadge(i)}<p class="sub">${i.id} · ${i.source==='system'?'系统周期任务':names[i.type]}</p></td><td>${esc(ceoCurrentHandler(i))}</td><td>${stages[i.type][i.stage]}<div class="progress"><span style="width:${i.progress||0}%"></span></div><span class="sub">${i.due}</span></td><td>${badge(i)}${i.blocked?`<p class="supply-error">${esc(i.blocked)}</p>`:''}</td><td><button data-open="${i.id}">${canAct(i)?'去处理':'查看'}</button></td></tr>`).join('')}</tbody></table></div>${arr.length?'':'<div class="empty">暂无符合条件的工作。</div>'}</section>`;}
function supplySchedule(){if(!supplyManager())return;const r=state.supply.rules;modal('周期任务规则与日期演示',`<form id="supply-rules"><div class="form-grid"><label class="field">图片整理生成日<select id="rule-weekday">${['周日','周一','周二','周三','周四','周五','周六'].map((n,j)=>`<option value="${j}" ${j===r.weekday?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">图片整理期限（含当天，自然日）<input id="rule-gallery-days" type="number" min="1" max="30" value="${r.galleryDays}" required></label><label class="field">默认整理员工<select id="rule-assignee">${taskEmployees(2).map(e=>`<option value="${e.id}" ${r.galleryAssignee===e.id?'selected':''}>${e.name}</option>`).join('')}</select></label><label class="field">清仓执行期限（自然日）<input type="number" id="rule-clearance-duration" min="1" max="60" value="${r.clearanceDuration}" required></label>${r.clearanceDays.map((n,j)=>`<label class="field">每月第 ${j+1} 次清仓生成日<input id="rule-day-${j}" type="number" min="1" max="28" required value="${n}"></label>`).join('')}${r.potentialDays.map((n,j)=>`<label class="field">每月第 ${j+1} 次潜力品生成日<input id="rule-potential-day-${j}" type="number" min="1" max="28" required value="${n}"></label>`).join('')}<label class="field">潜力品研究期限（自然日）<input id="rule-potential-duration" type="number" min="1" max="60" required value="${r.potentialDuration}"></label><label class="field">潜力品任务负责人<select id="rule-potential-assignee">${taskEmployees(2).map(e=>`<option value="${e.id}" ${r.potentialAssignee===e.id?'selected':''}>${e.name}</option>`).join('')}</select></label><label class="field wide">演示业务日期<input id="supply-date" type="date" value="${supplyToday()}" min="${supplyToday()}" max="${supplyDateAdd(supplyToday(),366)}" required></label></div><div class="notice">打开原型或推进演示日期时按规则生成任务，同一天同类任务不会重复。规则修改仅影响尚未生成的日期，历史任务保留。原型未部署服务器定时器，关闭页面后不会后台执行。</div><button class="primary">保存规则并检查待生成任务</button></form>`);$('#supply-rules').onsubmit=e=>{e.preventDefault();const days=[Number($('#rule-day-0').value),Number($('#rule-day-1').value)];if(days[0]>=days[1]){toast('两次清仓日期必须先后不同');return;}const potentialDays=[Number($('#rule-potential-day-0').value),Number($('#rule-potential-day-1').value)];if(potentialDays[0]>=potentialDays[1]){toast('两次潜力品日期必须先后不同');return;}const today=$('#supply-date').value;if(today<supplyToday()||today>supplyDateAdd(supplyToday(),366))return;const rules={potentialDays,potentialDuration:Number($('#rule-potential-duration').value),potentialAssignee:$('#rule-potential-assignee').value,weekday:Number($('#rule-weekday').value),galleryDays:Number($('#rule-gallery-days').value),galleryAssignee:$('#rule-assignee').value,clearanceDays:days,clearanceDuration:Number($('#rule-clearance-duration').value)};supplyCommit(null,(_,d)=>{d.supply.rules=rules;d.supply.today=today;supplyGenerate(d,today);},'规则已保存，周期任务已检查',false);};}
function supplyMetricDetail(kind){const m=supplyMetrics();const rows=kind==='pictures'?m.products.map(p=>[p.name,p.publishedAt,p.images.length+' 张图片（1 张主图）']):kind==='clearance'?m.clearances.map(({i,r})=>[i.title,i.shop,'¥'+r.forecastAmount+' · '+r.at]):(m[kind]||[]).map(i=>[i.title,i.completedAt||i.approvedAt,i.id]);modal(supplyMonth+' · 指标明细',previewTable(['来源记录','日期 / 项目','统计依据'],rows));}
async function supplyLoadImages(root=document){await Promise.allSettled([...root.querySelectorAll('[data-supply-image]')].map(async el=>{const id=el.dataset.supplyImage;try{if(!supplyURLs.has(id)){const f=await goalReadFile(id);if(!f)throw Error();supplyURLs.set(id,URL.createObjectURL(f.blob));}if(el.isConnected)el.src=supplyURLs.get(id);}catch{el.alt='图片未在当前浏览器找到';}}));}
async function supplyStoreAssets(files){if(files.length>200||files.some(f=>f.size>10*1024*1024)||files.reduce((a,f)=>a+f.size,0)>100*1024*1024)throw Error('每次最多200个文件；单个10MB、合计100MB以内');const records=await Promise.all(files.map(async f=>({id:newGoalId(),blob:f,name:f.name,type:f.type,size:f.size,path:f.webkitRelativePath||f.name,hash:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))).map(v=>v.toString(16).padStart(2,'0')).join('')})));if(records.length)await goalStoreFiles(records);return records.map(({id,name,type,size,path,hash})=>({id,name,type,size,path,hash}));}
function supplyImage(id,cls=''){return `<img class="${cls}" data-supply-image="${esc(id)}" alt="已上传商品图片">`;}
function supplyProductValid(p){return p.name?.trim()&&p.supplier?.trim()&&p.category?.trim()&&Number(p.weight)>0&&Number.isFinite(Number(p.labor))&&p.labor!==''&&Number(p.labor)>=0&&p.images.length;}
function supplyGalleryPage(){const cycles=items().filter(i=>i.type==='gallerycycle').sort((a,b)=>b.cycleDate.localeCompare(a.cycleDate));const products=state.supply.products.filter(p=>(p.name+p.supplier+p.category).includes(supplyProductSearch));return heading('整理供应商图片库','每周任务驱动整理；分类导入、补齐商品资料，审核后同步到运营选品。',supplyManager()?'<button id="supply-schedule">周期任务规则</button>':'')+`<div class="notice">文件夹推荐结构：供应商 / 分类 / 商品名称 / 图片。商品可含多张图；审核发布前仅供应链可见。当前图片存储在本浏览器，尚未接入服务器。</div><h2>每周整理任务</h2>${supplyWorkTable(cycles)}<div class="page-head"><h2>商品资料库 <small>${products.length} 款</small></h2><form id="supply-product-search"><input id="supply-product-query" value="${esc(supplyProductSearch)}" placeholder="搜索名称、供应商、分类"><button>搜索</button></form></div><div class="catalog-grid">${products.map(p=>`<article class="catalog-card">${supplyImage(p.images[0]?.id,'supply-product-photo')}<div class="catalog-card-body"><span class="badge ${p.publishedAt?'green':''}">${p.publishedAt?'已同步运营':'待整理 / 审核'}</span><h3>${esc(p.name)}</h3><p>${esc(p.supplier)} · ${esc(p.category)}</p><p class="sub">克重 ${p.weight||'待填'}g · 工费 ${p.labor===''?'待填':p.labor} 元/件 · ${p.images.length} 张图</p><button data-supply-product="${p.id}">查看 / 编辑商品资料</button></div></article>`).join('')}</div>${products.length?'':'<div class="empty">从上方每周任务进入，上传供应商产品文件夹开始整理。</div>'}`;}
function supplyDetail(id){const i=state.items.find(x=>x.id===id&&isSupply(x));if(!i||!supplyVisible(i)){toast('无权查看此事项');return;}activeRecordId=id;if(isLifeTask(i)){lifeTaskDetail(i);syncAIContext();return;}if(i.type==='develop')developmentDetail(i);if(i.type==='potentialcycle')potentialCycleDetail(i);if(i.type==='gallerycycle')galleryCycleDetail(i);if(i.type==='clearance')clearanceDetail(i);if(i.type==='potential')potentialDetail(i);$('.modal')?.classList.add('goal-modal');bindSupplyLocal();syncAIContext();}
function supplyHistory(i){return `<h3>过程记录</h3><div class="timeline">${i.history.map(h=>`<div>${esc(h)}</div>`).join('')}</div>`;}
function galleryCycleDetail(i){const products=state.supply.products.filter(p=>p.cycleId===i.id),editable=i.stage===0&&supplyCanAct(i);modal(i.title,`<div class="row-title">${badge(i)}<span>当前处理人：${esc(supplyHandler(i))} · 截止 ${i.due}</span></div><div class="flow">${stages.gallerycycle.map((n,j)=>`<span class="${j===i.stage?'current':''}">${n}</span>`).join('')}</div>${i.blocked?`<div class="notice rejection">${esc(i.blocked)}</div>`:''}${editable?`<section class="supply-upload"><h3>上传产品文件夹</h3><p class="sub">推荐：供应商 / 分类 / 商品名称 / 图片；同一商品文件夹的图片自动归组。扁平文件夹使用下方默认供应商与分类，每张图独立成品。</p><div class="form-grid"><label class="field">默认供应商<input id="import-supplier" value="云山工坊"></label><label class="field">默认分类<input id="import-category" value="银杯"></label></div><label class="field">选择整个文件夹<input type="file" id="supply-folder" webkitdirectory multiple accept="image/*"></label><label class="field">或选择多张图片<input type="file" id="supply-files" multiple accept="image/png,image/jpeg,image/webp,image/gif,image/avif"></label><div id="supply-import-preview"></div></section>`:''}<h3>本期商品 ${products.length} 款 · ${products.reduce((n,p)=>n+p.images.length,0)} 张图片</h3><div class="supply-mini-grid">${products.map(p=>`<button data-supply-product="${p.id}">${supplyImage(p.images[0]?.id)}<b>${esc(p.name)}</b><span class="sub">${supplyProductValid(p)?'资料齐全':'待补齐分类 / 克重 / 工费'}</span></button>`).join('')}</div>${editable?`<form id="gallery-submit"><label class="field">供应商覆盖与整理说明<textarea id="gallery-coverage" required placeholder="逐一说明本周供应商新品已整理，或哪些供应商无新品；遗漏及原因。">${esc(i.coverage||'')}</textarea></label><label><input type="checkbox" id="gallery-checked" required> 已核对全部供应商，本期新品均已整理；无新品情况已说明</label><div class="modal-footer"><button class="primary">完成整理，提交审核</button></div></form>`:''}${i.stage===1&&supplyManager()?`<p>整理说明：${esc(i.coverage)}</p><form id="gallery-review"><label class="field">审核意见<textarea id="gallery-review-note" required></textarea></label><button type="button" id="gallery-reject">退回补充</button><button class="primary">审核通过，发布到运营选品</button></form>`:''}${i.stage===2?'<div class="insight">本期整理已完成，商品和图片已同步运营选品。</div>':''}${supplyHistory(i)}`);
if(editable){const preview=input=>{const files=Array.from(input.files).filter(f=>/^image\/(png|jpeg|webp|gif|avif)$/.test(f.type));$('#supply-import-preview').innerHTML=`<p>选中 ${input.files.length} 个文件，其中 ${files.length} 张支持的图片。</p><button id="supply-import-confirm" ${files.length?'':'disabled'}>导入图片并生成商品</button>`;$('#supply-import-confirm').onclick=async()=>{const btn=$('#supply-import-confirm'),supplier=$('#import-supplier').value.trim(),category=$('#import-category').value.trim();if(!supplier||!category){toast('请填写默认供应商和分类');return;}btn.disabled=true;try{const assets=await supplyStoreAssets(files);supplyCommit(i.id,(item,d)=>{requireGoal(item.stage===0&&supplyCanAct(item),'当前不可导入');let added=0;for(const a of assets){const parts=a.path.split('/'),structured=parts.length>=4;const group=structured?parts.slice(0,-1).join('/'):a.path;let product=d.supply.products.find(p=>p.cycleId===i.id&&p.importGroup===group);if(product?.images.some(f=>f.path===a.path&&f.hash===a.hash))continue;if(!product){product={id:'PROD-'+newGoalId(),cycleId:i.id,importGroup:group,name:structured?parts.at(-2):a.name.replace(/\.[^.]+$/,''),supplier:structured?parts.at(-4):supplier,category:structured?parts.at(-3):category,weight:'',labor:'',price:0,moq:1,days:7,images:[],createdAt:supplyToday()};d.supply.products.push(product);}product.images.push(a);added++;}supplyAudit(d,item,'文件夹导入 '+added+' 张图片（同路径同内容图片去重）');},'已导入，请补齐商品克重和工费');}catch(e){toast(e.message);}finally{if(btn.isConnected)btn.disabled=false;}};};$('#supply-folder').onchange=e=>preview(e.target);$('#supply-files').onchange=e=>preview(e.target);$('#gallery-submit').onsubmit=e=>{e.preventDefault();const coverage=$('#gallery-coverage').value.trim();if(!coverage)return;supplyCommit(i.id,(item,d)=>{requireGoal(supplyCanAct(item)&&item.stage===0,'当前不可提交');const ps=d.supply.products.filter(p=>p.cycleId===i.id);requireGoal(ps.every(supplyProductValid),'请先补齐所有商品的名称、分类、供应商、克重和工费');item.coverage=coverage;item.stage=1;item.blocked='';supplyAudit(d,item,'提交图片整理审核：'+coverage);},'已提交负责人审核');};}
if($('#gallery-review')){const review=pass=>{const note=$('#gallery-review-note').value.trim();if(!note){toast('请填写审核意见');return;}supplyCommit(i.id,(item,d)=>{requireGoal(supplyManager()&&item.stage===1,'当前不可审核');item.stage=pass?2:0;item.blocked=pass?'':note;if(pass){const ps=d.supply.products.filter(p=>p.cycleId===i.id);requireGoal(ps.every(supplyProductValid),'商品资料不完整');ps.forEach(p=>p.publishedAt??=supplyToday());}supplyAudit(d,item,(pass?'审核通过并同步运营：':'退回整理：')+note);},pass?'已发布，运营选品和本月指标已更新':'已退回整理');};$('#gallery-review').onsubmit=e=>{e.preventDefault();review(true);};$('#gallery-reject').onclick=()=>review(false);}}
function supplyProductDetail(id){const p=state.supply.products.find(x=>x.id===id);if(!p)return;const cycle=state.items.find(i=>i.id===p.cycleId),edit=role===2&&(supplyManager()||cycle?.assigneeId===employeeId)&&cycle?.stage!==1;if(role!==0&&role!==2&&!p.publishedAt)return;modal(p.name,`<div class="supply-image-strip">${p.images.map(a=>supplyImage(a.id)).join('')}</div><form id="supply-product-form"><div class="form-grid">${[['name','产品名称','text'],['supplier','供应商','text'],['category','分类','text'],['weight','克重（g）','number'],['labor','工费（元/件）','number'],['price','参考采购价（元，可选）','number']].map(([k,n,t])=>`<label class="field">${n}<input data-product-field="${k}" type="${t}" ${t==='number'?'min="0" step="0.01"':''} value="${esc(p[k])}" ${edit?'':'disabled'} ${k==='price'?'':'required'}></label>`).join('')}</div><p class="sub">${p.publishedAt?'已发布资料保存后同步更新运营选品，不重复计入新增数。':'补齐资料后随本期整理任务审核发布。'}</p><div class="modal-footer"><button type="button" id="product-back">返回整理任务</button>${edit?'<button class="primary">保存商品资料</button>':''}</div></form>`);$('.modal').classList.add('goal-modal');supplyLoadImages();$('#product-back').onclick=()=>supplyDetail(p.cycleId);$('#supply-product-form').onsubmit=e=>{e.preventDefault();if(!edit)return;const v={};document.querySelectorAll('[data-product-field]').forEach(el=>v[el.dataset.productField]=el.type==='number'?Number(el.value):el.value.trim());if(!supplyProductValid({...p,...v})){toast('请补齐产品资料，克重必须大于0');return;}supplyCommit(null,(_,d)=>{const product=d.supply.products.find(x=>x.id===id);Object.assign(product,v);supplyAudit(d,d.items.find(x=>x.id===p.cycleId),'更新商品资料：'+v.name);},'商品资料已保存',false);supplyProductDetail(id);};}
let clearanceFilters=null,clearanceFilterIdentity='';
function clearanceDefaultFilters(){return {month:'current',carry:true,shop:'all',handler:'all',query:'',status:'all',sort:'attention',page:1,size:10};}
function clearanceFilterState(){const identity=`${role}:${level}:${employeeId}`;if(identity!==clearanceFilterIdentity||!clearanceFilters){clearanceFilters=clearanceDefaultFilters();clearanceFilterIdentity=identity;}return clearanceFilters;}
const clearanceLate=i=>i.stage!==3&&i.due<supplyToday();
function clearanceMatchesStatus(i,status){return status==='all'||status==='mine'&&supplyCanAct(i)||status==='draft'&&i.stage===0||status==='executing'&&i.stage===1||status==='review'&&i.stage===2||status==='done'&&i.stage===3||status==='late'&&clearanceLate(i);}
function clearanceListData(){const f=clearanceFilterState(),month=f.month==='current'?supplyToday().slice(0,7):f.month;const all=items().filter(i=>i.type==='clearance');const tokens=f.query.toLowerCase().split(/\s+/).filter(Boolean);const scoped=all.filter(i=>{const cycle=(i.cycleDate||i.createdAt||i.due||'').slice(0,7);return (month==='all'||cycle===month||f.carry&&cycle<month&&i.stage!==3)&&(f.shop==='all'||i.shop===f.shop)&&(f.handler==='all'||supplyHandler(i)===f.handler)&&tokens.every(token=>[i.id,i.title,i.shop,i.instructions,supplyHandler(i),...(i.products||[]).flatMap(p=>[p.id,p.name])].join(' ').toLowerCase().includes(token));});const shown=scoped.filter(i=>clearanceMatchesStatus(i,f.status));shown.sort((a,b)=>{if(f.sort==='newest')return (b.cycleDate||'').localeCompare(a.cycleDate||'')||b.id.localeCompare(a.id);if(f.sort==='deadline')return a.due.localeCompare(b.due)||a.id.localeCompare(b.id);if(f.sort==='amount')return Number(b.salesRecords?.at(-1)?.actualAmount||0)-Number(a.salesRecords?.at(-1)?.actualAmount||0)||a.id.localeCompare(b.id);return Number(a.stage===3)-Number(b.stage===3)||Number(clearanceLate(b))-Number(clearanceLate(a))||Number(supplyCanAct(b))-Number(supplyCanAct(a))||a.due.localeCompare(b.due)||a.id.localeCompare(b.id);});const pages=Math.max(1,Math.ceil(shown.length/f.size));f.page=Math.min(Math.max(1,f.page),pages);return {all,scoped,shown,pages,month,rows:shown.slice((f.page-1)*f.size,f.page*f.size)};}
function clearancePage(){const f=clearanceFilterState(),d=clearanceListData();const statuses=[['all','全部'],['mine','待我处理'],['draft','待制定方案'],['executing','执行中'],['review','待评价'],['done','已完成'],['late','延期']];const months=[...new Set(d.all.map(i=>(i.cycleDate||i.createdAt||i.due||'').slice(0,7)))].filter(Boolean).sort().reverse();const carry=d.scoped.filter(i=>d.month!=='all'&&(i.cycleDate||i.createdAt||i.due).slice(0,7)<d.month&&i.stage!==3).length;
return heading(role===1?'清仓执行与复盘':'组织清仓','按状态找工作，按项目与商品找记录；先处理延期和当前待办。',supplyManager()?'<button id="supply-schedule">周期任务规则</button>':'')+`<section class="panel clearance-filters"><form id="clearance-filter-form"><label class="field clearance-search-field">查找任务或商品<div class="clearance-search"><input id="clearance-search" value="${esc(f.query)}" placeholder="任务名称 / 编号 / 商品名称 / 商品编码"><button class="primary">搜索</button></div></label><label class="field">任务生成月份<select id="clearance-filter-month"><option value="current" ${f.month==='current'?'selected':''}>本月（${supplyToday().slice(0,7)}）</option><option value="all" ${f.month==='all'?'selected':''}>全部月份 / 历史任务</option>${months.map(m=>`<option value="${m}" ${f.month===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field">执行项目 / 店铺<select id="clearance-filter-shop"><option value="all">全部项目</option>${[...new Set([...d.all.map(i=>i.shop),...(f.shop==='all'?[]:[f.shop])])].map(s=>`<option value="${esc(s)}" ${f.shop===s?'selected':''}>${s==='公司'?'尚未分配项目':esc(s)}</option>`).join('')}</select></label><label class="field">当前处理人<select id="clearance-filter-handler"><option value="all">全部处理人</option>${[...new Set([...d.all.filter(i=>i.stage!==3).map(supplyHandler),...(f.handler==='all'?[]:[f.handler])])].map(s=>`<option value="${esc(s)}" ${f.handler===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><div class="clearance-filter-footer"><label><input type="checkbox" id="clearance-filter-carry" ${f.carry?'checked':''} ${d.month==='all'?'disabled':''}> 保留此前月份未完成任务</label><button type="button" id="clearance-filter-reset">重置筛选</button></div></form></section><div class="clearance-status-tabs" role="group" aria-label="清仓任务状态">${statuses.map(([v,n])=>`<button data-clearance-status="${v}" class="${f.status===v?'selected':''}" aria-pressed="${f.status===v}">${n}<strong>${d.scoped.filter(i=>clearanceMatchesStatus(i,v)).length}</strong></button>`).join('')}</div><div class="clearance-results"><div><b>找到 ${d.shown.length} 项任务</b><p class="sub">${d.month==='all'?'覆盖全部历史月份':`按生成月份 ${d.month} 查询${carry?'，包含此前未完成 '+carry+' 项':''}`}；“待我处理”和“延期”可与其他状态重叠。</p></div><label>排序 <select id="clearance-sort">${[['attention','优先处理：延期 / 待我处理'],['deadline','截止日期从近到远'],['newest','最新生成'],['amount','实际销售额从高到低']].map(([v,n])=>`<option value="${v}" ${f.sort===v?'selected':''}>${n}</option>`).join('')}</select></label></div><section class="panel"><div class="table-wrap"><table class="clearance-list-table"><thead><tr><th>清仓任务 / 周期</th><th>项目与商品</th><th>当前处理人 / 状态</th><th>销售进展</th><th>截止日期</th><th></th></tr></thead><tbody>${d.rows.map(i=>{const sales=i.salesRecords?.at(-1),previous=d.month!=='all'&&(i.cycleDate||i.createdAt||i.due).slice(0,7)<d.month;return `<tr data-supply-row="${i.id}" data-clearance-row="${i.id}"><td><button class="flat goal-title-link" data-open="${i.id}">${esc(i.title)}</button><p class="sub">${i.id} · 生成 ${esc(i.cycleDate||i.createdAt||'—')}</p>${previous?'<span class="badge yellow">跨月未完成</span>':''}</td><td><b>${i.shop==='公司'?'待分配项目':esc(i.shop)}</b><p class="sub">${i.products?.length?i.products.slice(0,2).map(p=>esc(p.id)+' '+esc(p.name)).join('<br>'):'待选择清仓商品'}${i.products?.length>2?'<br>等 '+i.products.length+' 款':''}</p></td><td>${esc(supplyHandler(i))}<p><span class="badge ${i.stage===3?'green':i.stage===2?'yellow':''}">${stages.clearance[i.stage]}</span></p>${i.blocked?`<p class="supply-error">${esc(i.blocked)}</p>`:''}</td><td>${i.stage===0?'<span class="sub">方案制定中</span>':`<b>实销 ¥${Number(sales?.actualAmount||0).toLocaleString()}</b><p class="sub">目标 ¥${Number(i.targetAmount||0).toLocaleString()} · 预估 ${sales?'¥'+Number(sales.forecastAmount).toLocaleString():'待填报'}</p><div class="progress"><span style="width:${Math.min(100,i.targetAmount?(sales?.actualAmount||0)/i.targetAmount*100:0)}%"></span></div>`}</td><td>${i.due}${clearanceLate(i)?`<p><span class="badge ${i.light==='red'?'red':'yellow'}">延期 ${taskDuration(i.due,supplyToday())-1} 天</span></p>`:''}</td><td><button data-open="${i.id}">${supplyCanAct(i)?'去处理':'查看'}</button></td></tr>`;}).join('')}</tbody></table></div>${d.shown.length?'':`<div class="empty"><h3>没有符合条件的清仓任务</h3><p>可以清除筛选，或跨全部月份查找历史记录。</p><button id="clearance-empty-reset">清除筛选</button> <button id="clearance-search-history">跨全部月份查找</button></div>`}</section><div class="catalog-pagination clearance-pagination"><label>每页 <select id="clearance-page-size">${[10,20,50].map(n=>`<option ${f.size===n?'selected':''}>${n}</option>`).join('')}</select> 项</label><button data-clearance-page="${f.page-1}" ${f.page===1?'disabled':''}>上一页</button><span>第 ${f.page} / ${d.pages} 页</span><button data-clearance-page="${f.page+1}" ${f.page===d.pages?'disabled':''}>下一页</button></div>`;}
function bindClearanceList(){if(!$('#clearance-filter-form'))return;const f=clearanceFilterState();const change=()=>{f.query=$('#clearance-search').value.trim();f.month=$('#clearance-filter-month').value;f.shop=$('#clearance-filter-shop').value;f.handler=$('#clearance-filter-handler').value;f.carry=$('#clearance-filter-carry').checked;f.page=1;render();};$('#clearance-filter-form').onsubmit=e=>{e.preventDefault();change();};['month','shop','handler','carry'].forEach(k=>$('#clearance-filter-'+k).onchange=change);const reset=()=>{clearanceFilters=clearanceDefaultFilters();render();};$('#clearance-filter-reset').onclick=reset;if($('#clearance-empty-reset'))$('#clearance-empty-reset').onclick=reset;if($('#clearance-search-history'))$('#clearance-search-history').onclick=()=>{f.month='all';f.page=1;render();};document.querySelectorAll('[data-clearance-status]').forEach(b=>b.onclick=()=>{f.status=b.dataset.clearanceStatus;f.page=1;render();});$('#clearance-sort').onchange=e=>{f.sort=e.target.value;f.page=1;render();};$('#clearance-page-size').onchange=e=>{f.size=Number(e.target.value);f.page=1;render();};document.querySelectorAll('[data-clearance-page]').forEach(b=>b.onclick=()=>{f.page=Number(b.dataset.clearancePage);render();$('#clearance-filter-form').scrollIntoView({block:'start'});});}

function clearanceLookup(code){if(code==='CY-0812')return {...catalogProducts[0],id:code};if(code==='CY-0823')return {...catalogProducts[1],id:code};return catalogProducts.find(p=>p.id===code)||state.supply.products.find(p=>p.id===code&&p.publishedAt);}
function clearanceDetail(i){const act=supplyCanAct(i),draft=i.stage===0&&act,latest=i.salesRecords?.at(-1);modal(i.title,`<div class="row-title">${badge(i)}<span>${esc(supplyHandler(i))} · 截止 ${i.due}</span></div><div class="flow">${stages.clearance.map((s,n)=>`<span class="${n===i.stage?'current':''}">${s}</span>`).join('')}</div>${i.blocked?`<div class="notice rejection">${esc(i.blocked)}</div>`:''}${draft?`<form id="clearance-plan"><h3>清仓商品与优惠</h3><div class="tabs"><input id="clearance-code" placeholder="输入商品编码，如 CY-0812"><button type="button" id="clearance-add">查询并添加商品</button></div><p class="sub">演示商品查询，可添加多款；每款填写原价和清仓价，自动计算优惠。</p><div id="clearance-lines"></div><div class="form-grid"><label class="field">整体期望目标销售额（元）<input id="clearance-target" type="number" min="0.01" step="0.01" required value="${i.targetAmount||''}"></label><label class="field">清仓执行项目 / 负责人<select id="clearance-shop">${shops.map(s=>`<option ${s===i.shop?'selected':''}>${s}</option>`).join('')}</select><span class="sub">项目负责人：林悦 · 事业主理人</span></label><label class="field">销售及复盘截止日<input id="clearance-due" type="date" required value="${i.due}"></label><label class="field">复盘评价人<select id="clearance-reviewer"><option value="manager-2">供应链负责人</option>${taskEmployees(2).map(e=>`<option value="${e.id}" ${i.reviewerId===e.id?'selected':''}>${e.name}</option>`).join('')}</select></label><label class="field wide">清仓说明和执行要求<textarea id="clearance-instructions" required>${esc(i.instructions||'')}</textarea></label></div><div class="modal-footer"><button type="button" id="clearance-save">保存方案草稿</button><button class="primary">下发给项目负责人</button></div></form>`:`<div class="detail-box"><p>项目：${esc(i.shop)} · 负责人：林悦</p><p>目标销售额：¥${Number(i.targetAmount||0).toLocaleString()} · 评价人：${esc(i.reviewerId==='manager-2'?'供应链负责人':taskEmployees(2).find(x=>x.id===i.reviewerId)?.name)}</p><p>${esc(i.instructions||'')}</p></div>${clearanceLines(i.products||[],false)}<div class="supply-sales-summary"><div><span>运营填写的预估金额</span><strong>¥${Number(latest?.forecastAmount||0).toLocaleString()}</strong></div><div><span>累计实际销售额</span><strong>¥${Number(latest?.actualAmount||0).toLocaleString()}</strong></div><div><span>目标完成率</span><strong>${i.targetAmount?Math.round((latest?.actualAmount||0)/i.targetAmount*100):0}%</strong></div></div>`}${act&&i.stage===1?i.acceptedAt?`<form id="clearance-sales"><div class="form-grid"><label class="field">预估最终清仓销售额（元）<input id="sales-forecast" type="number" min="0" step="0.01" required value="${latest?.forecastAmount??''}"></label><label class="field">累计实际销售额（元）<input id="sales-actual" type="number" min="0" step="0.01" required value="${latest?.actualAmount??''}"></label><label class="field">累计销售数量（件）<input id="sales-quantity" type="number" min="0" step="1" required value="${latest?.quantity??''}"></label><label class="field wide">销售进展 / 复盘信息<textarea id="sales-review" required placeholder="销售表现、采取的动作、未达预期原因与下次改进">${esc(latest?.review||'')}</textarea></label></div><div class="notice">填写的是本次清仓的累计数据，多次更新不重复累加。预估金额会实时进入供应链当月概览。</div><div class="modal-footer"><button type="button" id="sales-save">保存销售进展</button><button class="primary">提交复盘，请求评价</button></div></form>`:'<button class="primary" id="clearance-accept">确认接收清仓任务</button>':''}${act&&i.stage===2?`<form id="clearance-rating"><h3>评价本次清仓执行</h3><div class="supply-stars" role="group" aria-label="五星评分">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-label="${n}星" aria-pressed="false">☆</button>`).join('')}<span id="rating-label">请选择 1–5 星</span></div><input type="hidden" id="rating-value"><label class="field">评价与改进建议<textarea id="rating-comment" required></textarea></label><div class="modal-footer"><button type="button" id="clearance-return">退回补充复盘</button><button class="primary">提交评价，完成清仓</button></div></form>`:''}${i.rating?`<div class="insight"><b>${'★'.repeat(i.rating)}${'☆'.repeat(5-i.rating)} · ${i.rating} / 5</b><p>${esc(i.comment)}</p></div>`:''}${i.salesRecords?.length?`<h3>销售与复盘记录</h3>${[...i.salesRecords].reverse().map(r=>`<div class="detail-box"><b>${r.at} · 预估 ¥${r.forecastAmount} · 实销 ¥${r.actualAmount} · ${r.quantity} 件</b><p>${esc(r.review)}</p></div>`).join('')}`:''}${supplyHistory(i)}`);
if(draft){let lines=structuredClone(i.products||[]);const read=()=>{document.querySelectorAll('[data-clearance-line]').forEach(row=>{const p=lines.find(x=>x.id===row.dataset.clearanceLine);if(p){p.original=Number(row.querySelector('[data-original]').value);p.sale=Number(row.querySelector('[data-sale]').value);}});};const paint=()=>{$('#clearance-lines').innerHTML=clearanceLines(lines,true);document.querySelectorAll('[data-remove-code]').forEach(b=>b.onclick=()=>{read();lines=lines.filter(x=>x.id!==b.dataset.removeCode);paint();});document.querySelectorAll('[data-clearance-line] input').forEach(el=>el.oninput=()=>{read();const row=el.closest('[data-clearance-line]'),p=lines.find(x=>x.id===row.dataset.clearanceLine);row.querySelector('[data-discount]').textContent=p.original>0?`${(p.sale/p.original*10).toFixed(1)}折 · 省 ¥${(p.original-p.sale).toFixed(2)}`:'请填写原价';});};paint();$('#clearance-add').onclick=()=>{read();const code=$('#clearance-code').value.trim(),p=clearanceLookup(code);if(!p){toast('演示库未找到该编码，请使用提示中的商品编码');return;}if(lines.some(x=>x.id===p.id)){toast('该商品已加入');return;}lines.push({id:p.id,name:p.name,index:p.index,category:p.category,original:p.price||0,sale:0,imageId:p.images?.[0]?.id});paint();supplyLoadImages();$('#clearance-code').value='';};const plan=submit=>{read();const v={products:lines,targetAmount:Number($('#clearance-target').value),shop:$('#clearance-shop').value,due:$('#clearance-due').value,reviewerId:$('#clearance-reviewer').value,instructions:$('#clearance-instructions').value.trim()};if(submit&&(!lines.length||lines.some(p=>p.original<=0||p.sale<=0||p.sale>=p.original)||v.targetAmount<=0||!v.instructions||!v.due)){toast('请添加商品并填写有效的原价、低于原价的清仓价、目标金额、期限和执行要求');return;}supplyCommit(i.id,(item,d)=>{requireGoal(item.stage===0&&supplyManager(),'仅供应链负责人可安排清仓');Object.assign(item,v);if(submit)item.stage=1;supplyAudit(d,item,submit?'下发清仓给林悦 / '+v.shop+'；目标 ¥'+v.targetAmount:'保存清仓方案草稿');},submit?'已下发到项目负责人工作台':'草稿已保存');};$('#clearance-save').onclick=()=>plan(false);$('#clearance-plan').onsubmit=e=>{e.preventDefault();plan(true);};}
if($('#clearance-accept'))$('#clearance-accept').onclick=()=>supplyCommit(i.id,(item,d)=>{requireGoal(supplyCanAct(item)&&item.stage===1,'当前不可接收');item.acceptedAt=supplyToday();supplyAudit(d,item,'项目负责人确认接收清仓任务');},'已接收，可持续记录销售与复盘');
if($('#clearance-sales')){const report=submit=>{if(!$('#clearance-sales').reportValidity())return;const r={at:supplyToday(),forecastAmount:Number($('#sales-forecast').value),actualAmount:Number($('#sales-actual').value),quantity:Number($('#sales-quantity').value),review:$('#sales-review').value.trim()};if(!r.review)return;supplyCommit(i.id,(item,d)=>{requireGoal(supplyCanAct(item)&&item.stage===1,'当前不可提交销售记录');item.salesRecords.push(r);if(submit)item.stage=2;item.blocked='';supplyAudit(d,item,(submit?'提交复盘':'更新累计销售数据')+'：预估 ¥'+r.forecastAmount+'，实际 ¥'+r.actualAmount+'；'+r.review);},submit?'已提交指定评价人':'销售数据及概览指标已更新');};$('#sales-save').onclick=()=>report(false);$('#clearance-sales').onsubmit=e=>{e.preventDefault();report(true);};}
if($('#clearance-rating')){document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.rating);$('#rating-value').value=n;$('#rating-label').textContent=n+' / 5 星';document.querySelectorAll('[data-rating]').forEach(x=>{x.textContent=Number(x.dataset.rating)<=n?'★':'☆';x.setAttribute('aria-pressed',String(Number(x.dataset.rating)===n));});});const review=pass=>{const rating=Number($('#rating-value').value),comment=$('#rating-comment').value.trim();if(!comment||pass&&!(rating>=1&&rating<=5)){toast('请填写评论并选择1–5星评分');return;}supplyCommit(i.id,(item,d)=>{requireGoal(supplyCanAct(item)&&item.stage===2,'仅指定评价人可评价');item.stage=pass?3:1;item.blocked=pass?'':comment;if(pass){item.rating=rating;item.comment=comment;}supplyAudit(d,item,(pass?'完成清仓，评分 '+rating+' 星：':'退回补充复盘：')+comment);},pass?'评价已提交，清仓流程完成':'已退回项目负责人');};$('#clearance-return').onclick=()=>review(false);$('#clearance-rating').onsubmit=e=>{e.preventDefault();review(true);};}}
function clearanceLines(lines,edit){return `<div class="table-wrap"><table><thead><tr><th>清仓商品</th><th>原价</th><th>清仓价</th><th>优惠信息</th>${edit?'<th></th>':''}</tr></thead><tbody>${lines.map(p=>`<tr data-clearance-line="${esc(p.id)}"><td><div class="supply-code-product">${p.imageId?supplyImage(p.imageId):`<img src="${productImage(p)}" alt="${esc(p.name)}示意图">`}<div><b>${esc(p.name)}</b><p class="sub">${esc(p.id)}</p></div></div></td><td>${edit?`<input data-original type="number" min="0.01" step="0.01" value="${p.original}">`:'¥'+p.original}</td><td>${edit?`<input data-sale type="number" min="0.01" step="0.01" value="${p.sale}">`:'¥'+p.sale}</td><td data-discount>${p.original>0?(p.sale/p.original*10).toFixed(1)+'折 · 省 ¥'+(p.original-p.sale).toFixed(2):'请填写原价'}</td>${edit?`<td><button type="button" data-remove-code="${esc(p.id)}">移除</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function potentialCards(arr){return `<div class="supply-potential-grid">${arr.map(i=>{const complete=(i.dimensions||[]).filter((d,n)=>potentialDimensionValid(d,n)).length;return `<button class="panel supply-potential-card" data-open="${i.id}">${i.images?.length?supplyImage(i.images[0].id):'<div class="supply-idea">✧<span>从一个选品想法开始</span></div>'}<div><span class="badge ${i.stage===2?'green':''}">${stages.potential[i.stage]}</span><h3>${esc(i.title)}</h3><p class="sub">${esc(i.description.slice(0,70))}</p><div class="progress"><span style="width:${complete*20}%"></span></div><p class="sub">五维证据 ${complete}/5 · 跟踪 ${i.tracking?.length||0} 次</p>${i.stage===2?`<b>平均评分 ${(i.dimensions.reduce((s,d)=>s+d.score,0)/5).toFixed(1)} / 5</b>`:''}</div></button>`;}).join('')}</div>`;}
function potentialPage(){const all=items().filter(i=>i.type==='potential'),arr=all.filter(i=>potentialFilter==='all'||String(i.stage)===potentialFilter).filter(i=>(i.title+i.description).includes(potentialSearch));return heading('发现潜力品','先记录想法与图片，持续补充五维证据；资料齐备后，一次提交主管评审。',role===2?(supplyManager()?'<button id="supply-schedule">周期任务规则</button>':'')+'<button class="primary" id="potential-new">＋ 记录新想法</button>':'')+`<h2>每月两次 · 本期发现任务</h2>${supplyWorkTable(items().filter(i=>i.type==='potentialcycle').sort((a,b)=>b.cycleDate.localeCompare(a.cycleDate)))}<h2>潜力商品记录</h2><div class="tabs">${[['all','全部'],['0','记录与跟踪'],['1','待主管评审'],['2','评审通过']].map(([v,n])=>`<button data-potential-filter="${v}" class="${v===potentialFilter?'active':''}">${n} ${all.filter(i=>v==='all'||String(i.stage)===v).length}</button>`).join('')}<form id="potential-search-form"><input id="potential-query" value="${esc(potentialSearch)}" placeholder="搜索产品或想法"><button>搜索</button></form></div>${potentialCards(arr)}${arr.length?'':'<div class="empty">随手记下一款产品、一个机会或一张图片，后续再补充证据。</div>'}`;}
function potentialCreate(cycleId){if(role!==2)return;const cycles=state.items.filter(i=>i.type==='potentialcycle'&&i.stage!==2&&supplyVisible(i)&&(supplyManager()||i.assigneeId===employeeId)).sort((a,b)=>b.cycleDate.localeCompare(a.cycleDate));const suggested=typeof cycleId==='string'?cycleId:cycles[0]?.id;modal('记录潜力品想法',`<form id="potential-create"><label class="field">关联本期自动任务<select id="potential-cycle"><option value="">独立记录，不计入周期任务</option>${cycles.map(c=>`<option value="${c.id}" ${c.id===suggested?'selected':''}>${c.title}</option>`).join('')}</select></label><label class="field">产品名称 / 想法标题<input id="potential-title" required maxlength="120"></label><label class="field">想法和发现<textarea id="potential-idea" required></textarea></label><label class="field">产品图片（选填，可后续追加）<input type="file" id="potential-images" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label><button class="primary">保存想法，开始跟踪</button></form>`);$('#potential-create').onsubmit=async e=>{e.preventDefault();const title=$('#potential-title').value.trim(),description=$('#potential-idea').value.trim(),who=supplyOwner(),selectedCycle=$('#potential-cycle').value;if(!title||!description)return;const btn=$('#potential-create .primary');btn.disabled=true;try{const images=await supplyStoreAssets(Array.from($('#potential-images').files));let id;const ok=supplyCommit(null,(_,d)=>{requireGoal(role===2&&supplyOwner()===who,'身份已变化，请重新提交');const cycle=selectedCycle?d.items.find(x=>x.id===selectedCycle&&x.type==='potentialcycle'):null;requireGoal(!selectedCycle||cycle&&cycle.stage!==2&&(supplyManager()||cycle.assigneeId===employeeId),'当前周期不可关联');id='CJ-'+d.seq++;const i={id,type:'potential',cycleId:cycle?.id||'',title,description,center:2,shop:'公司',creatorId:cycle?.assigneeId||who,owner:developmentPerson(cycle?.assigneeId||who),stage:0,progress:0,due:cycle?.due||supplyDateAdd(supplyToday(),14),light:'green',createdAt:supplyToday(),images,dimensions:potentialDimensions.map(()=>({score:0,evidence:'',source:'',files:[]})),tracking:[],history:[]};d.items.push(i);supplyAudit(d,i,'记录潜力品想法：'+description);},'想法已保存',false);if(ok)supplyDetail(id);}catch(err){toast(err.message);}finally{if(btn.isConnected)btn.disabled=false;}};}
function potentialDimensionValid(d,n){return d&&d.score>=1&&d.score<=5&&Number.isInteger(d.score)&&d.evidence.trim()&&(n===4||d.source.trim()||d.files.length);}
function supplyEvidence(files){return files.map(f=>`<button type="button" data-supply-download="${f.id}">↓ ${esc(f.name)}</button>`).join('');}
function potentialDetail(i){const edit=i.stage===0&&supplyCanAct(i),review=i.stage===1&&supplyManager(),follow=role===2&&(supplyManager()||i.creatorId===supplyOwner());modal(i.title,`<div class="row-title">${badge(i)}<span>${stages.potential[i.stage]} · ${esc(i.owner)}</span></div><p>${esc(i.description)}</p>${i.blocked?`<div class="notice rejection">主管意见：${esc(i.blocked)}</div>`:''}<div class="supply-image-strip">${(i.images||[]).map(f=>supplyImage(f.id)).join('')}</div><div class="notice">五项各按1–5分评分：1低、3一般、5高。前四项需要证据说明及来源链接或附件，主观感受需写明判断依据。评分是人工判断，系统不代替证据核实。</div><form id="potential-assessment"><div class="supply-dimensions">${potentialDimensions.map((name,n)=>{const d=i.dimensions[n];return `<section class="supply-dimension"><div class="row-title"><h3>${n+1}. ${name}</h3><span class="badge ${potentialDimensionValid(d,n)?'green':''}">${potentialDimensionValid(d,n)?'证据齐全':'待补充'}</span></div><label class="field">评分<select data-dimension-score="${n}" ${edit?'':'disabled'}><option value="0">暂不评分</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${d.score===v?'selected':''}>${v} 分${v===1?' · 低':v===3?' · 一般':v===5?' · 高':''}</option>`).join('')}</select></label><label class="field">${n===4?'主观判断与依据':'数据、证据与判断说明'}<textarea data-dimension-evidence="${n}" ${edit?'':'disabled'} placeholder="记录具体数据、时间范围和判断逻辑">${esc(d.evidence)}</textarea></label><label class="field">来源链接（可选，可用附件代替）<input data-dimension-source="${n}" type="url" value="${esc(d.source)}" ${edit?'':'disabled'} placeholder="https://…"></label>${supplyEvidence(d.files)}${edit?`<label class="field">追加截图 / 证据文件<input type="file" data-dimension-files="${n}" multiple></label>`:''}</section>`;}).join('')}</div>${edit?'<div class="supply-sticky-actions"><span>可分次记录，不必一次填完</span><button type="button" id="potential-save">保存当前记录</button><button class="primary">提交主管评审</button></div>':''}</form>${review?'<form id="potential-review"><label class="field">主管评审意见<textarea id="potential-review-note" required></textarea></label><div class="modal-footer"><button type="button" id="potential-return">退回补充证据</button><button class="primary">评审通过，纳入概览</button></div></form>':''}${i.stage===2?`<div class="insight">评审通过 · ${i.approvedAt}<p>${esc(i.reviewNote)}</p></div>`:''}<h3>持续跟踪记录</h3>${follow?'<form id="potential-track"><label class="field">新增观察 / 跟踪记录<textarea id="potential-track-note" required placeholder="随时记录新的销量变化、竞品信息或你的想法"></textarea></label><label class="field">追加产品图片或资料<input type="file" id="potential-track-files" multiple></label><button>保存跟踪记录</button></form>':''}${[...(i.tracking||[])].reverse().map(t=>`<div class="detail-box"><b>${t.at}</b><p>${esc(t.note)}</p>${supplyEvidence(t.files)}</div>`).join('')}${supplyHistory(i)}`);
if(edit){const saveAssessment=async submit=>{const form=$('#potential-assessment');if(!form.reportValidity())return;const values=i.dimensions.map((d,n)=>({...d,score:Number($(`[data-dimension-score="${n}"]`).value),evidence:$(`[data-dimension-evidence="${n}"]`).value.trim(),source:$(`[data-dimension-source="${n}"]`).value.trim(),files:[...d.files]}));const uploads=i.dimensions.map((_,n)=>Array.from($(`[data-dimension-files="${n}"]`).files));form.querySelectorAll('button').forEach(b=>b.disabled=true);try{for(let n=0;n<5;n++)values[n].files.push(...await supplyStoreAssets(uploads[n]));if(submit&&!values.every(potentialDimensionValid)){toast('请补齐每个维度的评分和证据，前四项需来源或附件；可先保存当前记录');return;}supplyCommit(i.id,(item,d)=>{requireGoal(item.stage===0&&supplyCanAct(item),'当前不可修改评分');item.dimensions=values;item.updatedAt=supplyToday();if(submit){item.stage=1;item.blocked='';}supplyAudit(d,item,submit?'五维证据齐备，提交主管评审':'保存五维评分和证据草稿');},submit?'已提交主管评审':'评分和证据已保存');}catch(e){toast(e.message);}finally{if(form.isConnected)form.querySelectorAll('button').forEach(b=>b.disabled=false);}};$('#potential-save').onclick=()=>saveAssessment(false);$('#potential-assessment').onsubmit=e=>{e.preventDefault();if(edit)saveAssessment(true);};}
if(review){const assess=pass=>{const note=$('#potential-review-note').value.trim();if(!note){toast('请填写评审意见');return;}supplyCommit(i.id,(item,d)=>{requireGoal(supplyManager()&&item.stage===1,'仅主管可评审');if(pass)requireGoal(item.dimensions.every(potentialDimensionValid),'五维评分和证据不完整');item.stage=pass?2:0;item.blocked=pass?'':note;item.reviewNote=note;if(pass)item.approvedAt=supplyToday();supplyAudit(d,item,(pass?'潜力品评审通过：':'退回补充：')+note);},pass?'已通过，本月潜力品数量已更新':'已退回记录人');};$('#potential-review').onsubmit=e=>{e.preventDefault();assess(true);};$('#potential-return').onclick=()=>assess(false);}
if(follow)$('#potential-track').onsubmit=async e=>{e.preventDefault();const note=$('#potential-track-note').value.trim();if(!note)return;const btn=$('#potential-track button');btn.disabled=true;try{const files=await supplyStoreAssets(Array.from($('#potential-track-files').files));let pendingDimensions=null;if(edit){pendingDimensions=[];for(let n=0;n<5;n++)pendingDimensions.push({...i.dimensions[n],score:Number($(`[data-dimension-score="${n}"]`).value),evidence:$(`[data-dimension-evidence="${n}"]`).value.trim(),source:$(`[data-dimension-source="${n}"]`).value.trim(),files:[...i.dimensions[n].files,...await supplyStoreAssets(Array.from($(`[data-dimension-files="${n}"]`).files))]});}supplyCommit(i.id,(item,d)=>{requireGoal(role===2&&(supplyManager()||item.creatorId===supplyOwner()),'无权更新跟踪');if(pendingDimensions&&item.stage===0)item.dimensions=pendingDimensions;item.tracking.push({at:supplyToday(),note,files});item.images.push(...files.filter(f=>/^image\//.test(f.type)));supplyAudit(d,item,'补充跟踪：'+note);},'跟踪记录已保存');}catch(err){toast(err.message);}finally{if(btn.isConnected)btn.disabled=false;}};}
function bindSupplyLocal(){document.querySelectorAll('[data-cycle-potential]').forEach(b=>b.onclick=()=>potentialCreate(b.dataset.cyclePotential));document.querySelectorAll('[data-supply-product]').forEach(b=>b.onclick=()=>supplyProductDetail(b.dataset.supplyProduct));document.querySelectorAll('[data-supply-download]').forEach(b=>b.onclick=async()=>{try{const f=await goalReadFile(b.dataset.supplyDownload);if(!f)throw Error('文件不在当前浏览器中');goalDownload(f.blob,f.name);}catch(e){toast(e.message);}});supplyLoadImages();}
function bindSupply(){bindClearanceList();bindSupplyLocal();if($('#supply-schedule'))$('#supply-schedule').onclick=supplySchedule;if($('#supply-month'))$('#supply-month').onchange=e=>{if(e.target.value){supplyMonth=e.target.value;render();}};document.querySelectorAll('[data-supply-view]').forEach(b=>b.onclick=()=>{supplyView=b.dataset.supplyView;render();});document.querySelectorAll('[data-supply-status]').forEach(b=>b.onclick=()=>{supplyStatus=b.dataset.supplyStatus;render();});document.querySelectorAll('[data-supply-metric]').forEach(b=>b.onclick=()=>supplyMetricDetail(b.dataset.supplyMetric));if($('#supply-product-search'))$('#supply-product-search').onsubmit=e=>{e.preventDefault();supplyProductSearch=$('#supply-product-query').value.trim();render();};if($('#potential-new'))$('#potential-new').onclick=potentialCreate;if($('#potential-search-form'))$('#potential-search-form').onsubmit=e=>{e.preventDefault();potentialSearch=$('#potential-query').value.trim();render();};document.querySelectorAll('[data-potential-filter]').forEach(b=>b.onclick=()=>{potentialFilter=b.dataset.potentialFilter;render();});}
function publishedCatalog(){return [...state.supply.products.filter(p=>p.publishedAt).map((p,n)=>({...p,index:100000+n})),...catalogProducts];}
function syncPotentialCycles(d){for(const cycle of d.items.filter(i=>i.type==='potentialcycle')){const products=d.items.filter(i=>i.type==='potential'&&i.cycleId===cycle.id);const stage=products.length&&products.every(i=>i.stage===2)?2:products.some(i=>i.stage===1)?1:0;const progress=products.length?Math.round(products.filter(i=>i.stage===2).length/products.length*100):0;if(stage!==cycle.stage){cycle.stage=stage;cycle.blocked=products.some(i=>i.blocked)?'本期商品有评审退回，请补充证据后重新提交。':'';supplyAudit(d,cycle,stage===2?'本期全部 '+products.length+' 款潜力品通过主管评审，周期任务完成':stage===1?'本期商品已提交主管评审':'本期仍有商品需要研究或补充证据');}cycle.progress=progress;}}
function potentialCycleDetail(i){const products=state.items.filter(p=>p.type==='potential'&&p.cycleId===i.id&&visible(p));const canCreate=i.stage!==2&&role===2&&(supplyManager()||employeeId===i.assigneeId);modal(i.title,`<div class="row-title">${badge(i)}<span>负责人：${esc(developmentPerson(i.assigneeId))} · 截止 ${i.due}</span></div><div class="notice">每月自动触发两次。每期至少记录一款商品；关联商品均通过主管评审后，本任务自动完成。记录和评审都在商品卡片内进行。</div><div class="supply-sales-summary"><div><span>关联潜力商品</span><strong>${products.length}</strong></div><div><span>待主管评审</span><strong>${products.filter(p=>p.stage===1).length}</strong></div><div><span>评审通过</span><strong>${products.filter(p=>p.stage===2).length}</strong></div></div>${canCreate?`<button class="primary" data-cycle-potential="${i.id}">＋ 记录本期潜力商品</button>`:''}${potentialCards(products)}${products.length?'':'<div class="empty">从想法或图片开始记录，后续持续补充五维证据。</div>'}${supplyHistory(i)}`);document.querySelectorAll('.modal [data-open]').forEach(b=>b.onclick=()=>supplyDetail(b.dataset.open));}
